CREATE OR REPLACE FUNCTION public.pamda_admin_registrar_perfil(p_user_id uuid, p_username text, p_display_name text, p_role text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF NOT public.pamda_is_admin() THEN RAISE EXCEPTION 'Acesso negado'; END IF;
 IF p_user_id IS NULL OR p_username IS NULL OR btrim(p_username)='' OR p_display_name IS NULL OR btrim(p_display_name)='' THEN
  RAISE EXCEPTION 'Dados inválidos';
 END IF;
 INSERT INTO public.erp_user_profiles(user_id,username,display_name,role,active)
 VALUES(p_user_id,lower(btrim(p_username)),btrim(p_display_name),p_role,true);
 INSERT INTO public.erp_access_audit(actor_user_id,target_user_id,action,details)
 VALUES((SELECT auth.uid()),p_user_id,'registrar_perfil',jsonb_build_object('role',p_role));
END; $function$

CREATE OR REPLACE FUNCTION public.pamda_cadastrar_kit(p_capa_id uuid, p_servico_id uuid, p_preco_venda numeric DEFAULT NULL::numeric, p_custo_gerencial numeric DEFAULT NULL::numeric)
 RETURNS TABLE(kit_id uuid, codigo text, sku text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    v_capa public.products%ROWTYPE;
    v_servico public.products%ROWTYPE;
    v_codigo BIGINT;
    v_nome TEXT;
    v_sku TEXT;
    v_modelo TEXT;
    v_preco NUMERIC;
    v_custo NUMERIC;
    v_kit_id UUID;
BEGIN
    -- Somente administrador ativo
    IF auth.uid() IS NULL OR NOT EXISTS (
        SELECT 1
        FROM public.erp_user_profiles p
        WHERE p.user_id = auth.uid()
          AND p.role = 'admin_gerencial'
          AND p.active = TRUE
    ) THEN
        RAISE EXCEPTION 'Acesso não autorizado'
            USING ERRCODE = '42501';
    END IF;

    IF p_preco_venda < 0 OR p_custo_gerencial < 0 THEN
        RAISE EXCEPTION 'Custos e preços inválidos';
    END IF;

    -- Buscar capa física
    SELECT *
    INTO v_capa
    FROM public.products
    WHERE id = p_capa_id
      AND type = 'fisico'
      AND active = TRUE
    FOR SHARE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Capa física não encontrada';
    END IF;

    -- Buscar serviço
    SELECT *
    INTO v_servico
    FROM public.products
    WHERE id = p_servico_id
      AND type = 'servico'
      AND active = TRUE
    FOR SHARE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Serviço não encontrado';
    END IF;

    IF v_capa.code !~ '^[0-9]+$'
       OR v_capa.code::BIGINT NOT BETWEEN 101 AND 19999
    THEN
        RAISE EXCEPTION 'Código físico fora da faixa permitida';
    END IF;

    -- Caso especial: capa carteira
    IF v_capa.sku = 'CAP-CARTEIRA' THEN

        IF v_servico.sku = 'SRV-DTF-CARTEIRA-1F' THEN
            v_codigo := 20000 + v_capa.code::BIGINT;
            v_sku := 'KIT-CARTEIRA-1F';
            v_nome := 'Capa Carteira em Couro Sintético Personalizada - 1 face';
            v_preco := 45;

        ELSIF v_servico.sku = 'SRV-DTF-CARTEIRA-2F' THEN
            v_codigo := 40000 + v_capa.code::BIGINT;
            v_sku := 'KIT-CARTEIRA-2F';
            v_nome := 'Capa Carteira em Couro Sintético Personalizada - 2 faces';
            v_preco := 60;

        ELSE
            RAISE EXCEPTION 'Serviço incompatível com capa carteira';
        END IF;

    ELSE
        -- Kits normais utilizam a impressão interna.
        IF v_servico.sku <> 'SRV-DTF-UV' THEN
            RAISE EXCEPTION 'Serviço incompatível com a capa';
        END IF;

        v_codigo := 20000 + v_capa.code::BIGINT;

        CASE v_capa.sku
            WHEN 'CAP-MAGSAFE' THEN
                v_sku := 'KIT-MAGSAFE';
                v_nome := 'Capa personalizada MagSafe';
                v_preco := 35;

            WHEN 'CAP-SPACE' THEN
                v_sku := 'KIT-SPACE';
                v_nome := 'Capa personalizada Space';
                v_preco := 35;

            WHEN 'CAP-VELUDO' THEN
                v_sku := 'KIT-VELUDO';
                v_nome := 'Capa personalizada Veludo';
                v_preco := 35;

            ELSE
                v_sku := 'KIT-' || v_capa.sku;

                v_modelo := COALESCE(
                    NULLIF(BTRIM(v_capa.model_phone), ''),
                    NULLIF(
                        BTRIM(SPLIT_PART(v_capa.name, ' - ', 2)),
                        ''
                    )
                );

                IF v_modelo IS NULL THEN
                    RAISE EXCEPTION 'Modelo da capa não informado';
                END IF;

                v_nome :=
                    'Capa personalizada TPU transparente - '
                    || v_modelo;

                IF v_capa.code::BIGINT BETWEEN 101 AND 200 THEN
                    v_preco := NULL;
                ELSE
                    v_preco := 25;
                END IF;
        END CASE;
    END IF;

    -- Permitir preço específico informado pelo administrador.
    v_preco := COALESCE(p_preco_venda, v_preco);

    IF v_preco IS NULL THEN
        RAISE EXCEPTION 'Informe o preço deste kit especial';
    END IF;

    -- Não transformar custos desconhecidos em zero.
    IF v_capa.current_cost IS NOT NULL
       AND v_servico.current_cost IS NOT NULL THEN
        v_custo :=
            v_capa.current_cost + v_servico.current_cost;
    ELSE
        v_custo := NULL;
    END IF;

    -- Criar o kit oficial.
    INSERT INTO public.products (
        code, sku, name, description,
        category, brand, model_phone,
        type, current_cost, managerial_cost,
        sale_price, controls_inventory,
        current_inventory, min_inventory,
        stock_verified, image_url,
        active, b2b_site_visible
    )
    VALUES (
        v_codigo::TEXT,
        v_sku,
        v_nome,
        'Kit composto: ' || v_capa.name ||
            ' + ' || v_servico.name,
        'Kits Personalizados',
        'Pamda',
        v_capa.model_phone,
        'kit',
        v_custo,
        p_custo_gerencial,
        v_preco,
        FALSE,
        0,
        0,
        FALSE,
        v_capa.image_url,
        TRUE,
        FALSE
    )
    RETURNING id INTO v_kit_id;

    -- Relacionar a capa física.
    INSERT INTO public.kit_components (
        kit_product_id,
        component_product_id,
        quantity,
        sort_order
    )
    VALUES (v_kit_id, v_capa.id, 1, 1);

    -- Relacionar a impressão.
    INSERT INTO public.kit_components (
        kit_product_id,
        component_product_id,
        quantity,
        sort_order
    )
    VALUES (v_kit_id, v_servico.id, 1, 2);

    RETURN QUERY
    SELECT v_kit_id, v_codigo::TEXT, v_sku;
END;
$function$

CREATE OR REPLACE FUNCTION public.pamda_admin_definir_permissao(p_user_id uuid, p_permission text, p_allowed boolean, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF NOT public.pamda_is_admin() THEN RAISE EXCEPTION 'Acesso negado'; END IF;
 IF p_user_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.erp_user_profiles WHERE user_id=p_user_id) THEN
   RAISE EXCEPTION 'Usuário inexistente';
 END IF;
 IF p_permission IS NULL OR NOT EXISTS(SELECT 1 FROM public.erp_permission_catalog WHERE key=p_permission) THEN
   RAISE EXCEPTION 'Permissão inválida';
 END IF;
 IF p_allowed IS NULL THEN RAISE EXCEPTION 'Decisão obrigatória'; END IF;
 INSERT INTO public.erp_user_permission_overrides(user_id,permission_key,allowed,reason,assigned_by,updated_at)
 VALUES(p_user_id,p_permission,p_allowed,p_reason,(SELECT auth.uid()),now())
 ON CONFLICT(user_id,permission_key) DO UPDATE SET
 allowed=EXCLUDED.allowed,reason=EXCLUDED.reason,assigned_by=EXCLUDED.assigned_by,updated_at=now();
 INSERT INTO public.erp_access_audit(actor_user_id,target_user_id,action,details)
 VALUES((SELECT auth.uid()),p_user_id,'definir_permissao',
 jsonb_build_object('permission',p_permission,'allowed',p_allowed,'reason',p_reason));
END; $function$

CREATE OR REPLACE FUNCTION public.pamda_admin_atualizar_perfil(p_user_id uuid, p_role text, p_active boolean, p_display_name text, p_can_view_financial_metrics boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF NOT public.pamda_is_admin() THEN RAISE EXCEPTION 'Acesso negado'; END IF;
 IF p_user_id IS NULL OR p_role IS NULL OR p_active IS NULL OR p_display_name IS NULL OR btrim(p_display_name)='' OR p_can_view_financial_metrics IS NULL
 THEN RAISE EXCEPTION 'Dados inválidos'; END IF;
 IF p_user_id=(SELECT auth.uid()) AND (NOT p_active OR p_role<>'admin_gerencial') THEN
  RAISE EXCEPTION 'Não é permitido remover o próprio acesso administrativo';
 END IF;
 UPDATE public.erp_user_profiles SET role=p_role,active=p_active,
 display_name=btrim(p_display_name),can_view_financial_metrics=p_can_view_financial_metrics,updated_at=now()
 WHERE user_id=p_user_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Perfil não encontrado'; END IF;
 INSERT INTO public.erp_access_audit(actor_user_id,target_user_id,action,details)
 VALUES((SELECT auth.uid()),p_user_id,'atualizar_perfil',jsonb_build_object('role',p_role,'active',p_active,'can_view_financial_metrics',p_can_view_financial_metrics));
END; $function$

CREATE OR REPLACE FUNCTION public.pamda_descartar_venda_vazia(p_venda_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 v_actor uuid := (SELECT auth.uid());
 v_sale public.erp_sales%ROWTYPE;
BEGIN
 IF v_actor IS NULL OR NOT public.pamda_has_permission('sales.draft') THEN
  RAISE EXCEPTION 'Acesso negado';
 END IF;
 IF p_venda_id IS NULL THEN RAISE EXCEPTION 'Venda obrigatória'; END IF;
 SELECT * INTO v_sale FROM public.erp_sales WHERE id=p_venda_id FOR UPDATE;
 IF NOT FOUND THEN RETURN false; END IF;
 IF v_sale.created_by<>v_actor AND NOT public.pamda_is_admin() THEN
  RAISE EXCEPTION 'Somente o responsável pode descartar a venda vazia';
 END IF;
 IF v_sale.status<>'draft' OR v_sale.first_product_at IS NOT NULL
   OR EXISTS (SELECT 1 FROM public.erp_sale_items WHERE sale_id=p_venda_id) THEN
  RAISE EXCEPTION 'Venda já utilizou produtos ou foi encerrada; não pode ser descartada';
 END IF;
 DELETE FROM public.erp_sale_events WHERE sale_id=p_venda_id;
 DELETE FROM public.erp_sales WHERE id=p_venda_id;
 IF v_sale.order_number IS NOT NULL THEN
  INSERT INTO public.erp_reusable_order_numbers(order_number)
  VALUES(v_sale.order_number)
  ON CONFLICT(order_number) DO NOTHING;
  INSERT INTO public.erp_empty_sale_discards(
    discarded_sale_id,provisional_number,actor_user_id
  ) VALUES(p_venda_id,v_sale.order_number,v_actor);
 END IF;
 RETURN true;
END; $function$

CREATE OR REPLACE FUNCTION public.pamda_saldo_credito_teste(p_customer_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_amount numeric;
BEGIN
 IF NOT (public.pamda_is_admin() OR public.pamda_has_permission('sales.draft')) THEN
   RAISE EXCEPTION 'Acesso negado' USING ERRCODE='42501';
 END IF;
 IF p_customer_id IS NULL OR NOT EXISTS(
 SELECT 1 FROM public.customers WHERE id=p_customer_id AND active) THEN
   RAISE EXCEPTION 'Cliente ativo não encontrado';
 END IF;
 SELECT COALESCE(SUM(amount),0) INTO v_amount
 FROM public.erp_customer_credit_test_ledger WHERE customer_id=p_customer_id;
 RETURN v_amount;
END;
$function$

CREATE OR REPLACE FUNCTION public.pamda_conceder_credito_teste(p_customer_id uuid, p_amount numeric, p_reason text, p_request_key uuid, p_reference text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_actor uuid := (SELECT auth.uid());v_id uuid;v_existing record;
BEGIN
 IF NOT public.pamda_is_admin() THEN
  RAISE EXCEPTION 'Apenas administrador pode conceder crédito de teste'
  USING ERRCODE='42501';
 END IF;
 IF p_amount IS NULL OR p_amount<=0 OR p_amount>1000000 OR
  p_reason IS NULL OR length(btrim(p_reason))<5 OR p_request_key IS NULL THEN
  RAISE EXCEPTION 'Valor, motivo ou chave de requisição inválidos';
 END IF;
 PERFORM 1 FROM public.customers WHERE id=p_customer_id AND active FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Cliente ativo não encontrado'; END IF;
 SELECT id,customer_id,amount,reason INTO v_existing
 FROM public.erp_customer_credit_test_ledger WHERE request_key=p_request_key;
 IF FOUND THEN
   IF v_existing.customer_id IS DISTINCT FROM p_customer_id OR
      v_existing.amount IS DISTINCT FROM p_amount OR
      v_existing.reason IS DISTINCT FROM btrim(p_reason) THEN
     RAISE EXCEPTION 'Chave de requisição reutilizada com dados diferentes';
   END IF;
   RETURN v_existing.id;
 END IF;
 INSERT INTO public.erp_customer_credit_test_ledger(
 customer_id,kind,amount,reason,reference,actor_user_id,request_key)
 VALUES(p_customer_id,'grant',p_amount,btrim(p_reason),p_reference,v_actor,p_request_key)
 RETURNING id INTO v_id;
 RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.pamda_finalizar_venda_teste(p_sale_id uuid, p_payments jsonb, p_request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 v_actor uuid := (SELECT auth.uid());
 v_sale public.erp_sales%ROWTYPE;
 v_p jsonb;
 v_status text;
 v_channel text;
 v_code text;
 v_amount numeric;
 v_sum numeric := 0;
 v_method_id uuid;
 v_ledger_balance numeric;
 v_ledger_key uuid;
 v_payment_count integer;
 v_receipt jsonb;
 v_result jsonb;
 v_scheduled timestamptz;
 v_reference text;
BEGIN
 IF NOT public.pamda_is_admin() THEN
  RAISE EXCEPTION 'Finalização de teste restrita ao administrador'
  USING ERRCODE='42501';
 END IF;
 IF p_sale_id IS NULL OR p_request_key IS NULL OR
    p_payments IS NULL OR jsonb_typeof(p_payments)<>'array' OR
    jsonb_array_length(p_payments)>20 THEN
  RAISE EXCEPTION 'Parâmetros de finalização inválidos';
 END IF;
 SELECT * INTO v_sale FROM public.erp_sales WHERE id=p_sale_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Pedido não encontrado'; END IF;

 IF v_sale.status='confirmed' AND v_sale.is_test AND
    v_sale.test_finalize_key=p_request_key THEN
  SELECT jsonb_build_object('sale_id',v_sale.id,'order_number',v_sale.order_number,
   'status','confirmed','test_only',true,
   'receipt_id',r.id,'receipt_number',r.receipt_number)
  INTO v_result FROM public.erp_sale_test_receipts r WHERE r.sale_id=v_sale.id;
  IF v_result IS NULL THEN RAISE EXCEPTION 'Finalização anterior incompleta'; END IF;
  RETURN v_result;
 END IF;
 IF v_sale.status<>'draft' OR NOT v_sale.is_test THEN
  RAISE EXCEPTION 'Somente pendência de teste pode ser finalizada';
 END IF;
 IF v_sale.first_product_at IS NULL OR v_sale.order_number IS NULL OR
   NOT EXISTS(SELECT 1 FROM public.erp_sale_items WHERE sale_id=p_sale_id) THEN
  RAISE EXCEPTION 'Inclua pelo menos um produto antes de finalizar';
 END IF;
 IF NOT v_sale.shipping_confirmed THEN
  RAISE EXCEPTION 'Confirme o frete da venda, inclusive quando for zero';
 END IF;
 IF v_sale.total < 0 THEN RAISE EXCEPTION 'Total inválido'; END IF;
 IF v_sale.total>0 AND jsonb_array_length(p_payments)=0 THEN
  RAISE EXCEPTION 'Informe o pagamento da venda';
 END IF;

 -- Lock customer so concurrent grants/redemptions of test credits serialize.
 PERFORM 1 FROM public.customers WHERE id=v_sale.customer_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Cliente não encontrado'; END IF;
 SELECT COALESCE(SUM(amount),0) INTO v_ledger_balance
 FROM public.erp_customer_credit_test_ledger WHERE customer_id=v_sale.customer_id;

 FOR v_p IN SELECT value FROM jsonb_array_elements(p_payments) LOOP
  IF jsonb_typeof(v_p)<>'object' THEN RAISE EXCEPTION 'Pagamento inválido'; END IF;
  v_code:=v_p->>'method_code';
  v_status:=COALESCE(v_p->>'status','pending');
  v_channel:=COALESCE(v_p->>'channel','erp');
  v_reference:=NULLIF(btrim(coalesce(v_p->>'reference','')),'');
  IF v_code IS NULL OR v_status NOT IN ('scheduled','pending','paid') OR
    v_channel NOT IN ('erp','site') THEN
   RAISE EXCEPTION 'Método, status ou canal de pagamento inválidos';
  END IF;
  v_amount:=(v_p->>'amount')::numeric;
  IF v_amount IS NULL OR v_amount<=0 OR v_amount>1000000 OR
     v_amount <> round(v_amount,2) THEN
   RAISE EXCEPTION 'Valor do pagamento inválido';
  END IF;
  SELECT id INTO v_method_id FROM public.erp_payment_methods
  WHERE code=v_code AND active;
  IF NOT FOUND THEN RAISE EXCEPTION 'Forma de pagamento desconhecida ou inativa: %',v_code; END IF;

  v_scheduled:=NULL;
  IF v_status='scheduled' THEN
    IF v_p->>'scheduled_for' IS NULL THEN
      RAISE EXCEPTION 'Informe data do pagamento agendado';
    END IF;
    v_scheduled:=(v_p->>'scheduled_for')::timestamptz;
  END IF;
  IF v_channel='site' AND v_status='paid' THEN
   RAISE EXCEPTION 'Pagamento no site depende de validação do provedor, não do navegador';
  END IF;
  IF v_code='credito_cliente' THEN
   IF v_status<>'paid' OR v_channel<>'erp' THEN
    RAISE EXCEPTION 'Crédito de cliente deve ser aplicado imediatamente pelo ERP no teste';
   END IF;
   IF v_ledger_balance < v_amount THEN
    RAISE EXCEPTION 'Saldo de crédito de teste insuficiente';
   END IF;
   v_ledger_balance:=v_ledger_balance-v_amount;
   v_ledger_key:=gen_random_uuid();
   INSERT INTO public.erp_customer_credit_test_ledger(
    customer_id,sale_id,kind,amount,reason,reference,actor_user_id,request_key
   ) VALUES(v_sale.customer_id,p_sale_id,'redeem',-v_amount,
     'Aplicação do crédito no pedido de teste',v_sale.order_number::text,v_actor,v_ledger_key);
  END IF;
  INSERT INTO public.erp_sale_test_payments(
   sale_id,payment_method_id,amount,status,channel,scheduled_for,paid_at,
   provider_reference,confirmed_by,created_by
  ) VALUES(p_sale_id,v_method_id,v_amount,v_status,v_channel,v_scheduled,
   CASE WHEN v_status='paid' THEN now() ELSE NULL END,v_reference,
   CASE WHEN v_status='paid' THEN v_actor ELSE NULL END,v_actor);
  v_sum:=v_sum+v_amount;
 END LOOP;

 IF v_sum IS DISTINCT FROM v_sale.total THEN
  RAISE EXCEPTION 'Soma dos pagamentos (R$ %) diferente do total (R$ %)',v_sum,v_sale.total;
 END IF;
 UPDATE public.erp_sales SET status='confirmed',confirmed_at=now(),
  test_confirmed_by=v_actor,test_finalize_key=p_request_key,updated_at=now()
 WHERE id=p_sale_id;

 SELECT jsonb_build_object(
  'test_only',true,'fiscal',false,
  'notice','DOCUMENTO DE TESTE - SEM VALOR FISCAL OU COBRANÇA REAL',
  'order_number',v_sale.order_number,'customer',v_sale.customer_snapshot,
  'branch',v_sale.branch_snapshot,'seller',v_sale.seller_snapshot,
  'subtotal',v_sale.subtotal,'discount',v_sale.discount_amount,
  'shipping',v_sale.shipping_charged,'total',v_sale.total,
  'notes',v_sale.notes,
  'items',(SELECT coalesce(jsonb_agg(jsonb_build_object('product_code',i.product_code_snapshot,
     'sku',i.product_sku_snapshot,'name',i.description_snapshot,'quantity',i.quantity,
     'unit_price',i.negotiated_unit_price,'line_subtotal',i.line_subtotal,
     'customization',i.customization) ORDER BY i.created_at,i.id),'[]'::jsonb)
     FROM public.erp_sale_items i WHERE i.sale_id=p_sale_id),
  'payments',(SELECT coalesce(jsonb_agg(jsonb_build_object('method_code',m.code,
    'amount',x.amount,'status',x.status,'channel',x.channel,
    'scheduled_for',x.scheduled_for) ORDER BY x.created_at,x.id),'[]'::jsonb)
    FROM public.erp_sale_test_payments x JOIN public.erp_payment_methods m ON m.id=x.payment_method_id
    WHERE x.sale_id=p_sale_id)
 ) INTO v_receipt;

 INSERT INTO public.erp_sale_test_receipts(sale_id,receipt_number,receipt_snapshot)
 VALUES(p_sale_id,v_sale.order_number::text,v_receipt);

 INSERT INTO public.erp_sale_events(sale_id,actor_user_id,event_type,details)
 VALUES(p_sale_id,v_actor,'test_sale_finalized',
  jsonb_build_object('number',v_sale.order_number,'test_only',true,
     'total',v_sale.total,'payment_count',jsonb_array_length(p_payments)));

 SELECT jsonb_build_object('sale_id',p_sale_id,'order_number',v_sale.order_number,
  'status','confirmed','test_only',true,'receipt_number',v_sale.order_number::text,
  'receipt_id',r.id)
 INTO v_result FROM public.erp_sale_test_receipts r WHERE r.sale_id=p_sale_id;
 RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.pamda_confirmar_pagamento_teste(p_payment_id uuid, p_reference text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_actor uuid := (SELECT auth.uid());v_pay public.erp_sale_test_payments%ROWTYPE;
BEGIN
 IF NOT public.pamda_is_admin() THEN
  RAISE EXCEPTION 'Somente administrador pode confirmar pagamento de teste'
  USING ERRCODE='42501';
 END IF;
 SELECT * INTO v_pay FROM public.erp_sale_test_payments WHERE id=p_payment_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Pagamento não encontrado'; END IF;
 IF v_pay.channel='site' THEN
  RAISE EXCEPTION 'Pagamento do site exige confirmação verificada pelo provedor';
 END IF;
 IF v_pay.status='paid' THEN RETURN; END IF;
 IF p_reference IS NULL OR length(btrim(p_reference))<3 THEN
  RAISE EXCEPTION 'Informe referência ou justificativa da confirmação';
 END IF;
 UPDATE public.erp_sale_test_payments SET status='paid',paid_at=now(),
   confirmed_by=v_actor,provider_reference=btrim(p_reference)
 WHERE id=p_payment_id;
 INSERT INTO public.erp_sale_events(sale_id,actor_user_id,event_type,details)
 VALUES(v_pay.sale_id,v_actor,'test_payment_confirmed',
  jsonb_build_object('payment_id',p_payment_id,'reference',btrim(p_reference)));
END;
$function$

CREATE OR REPLACE FUNCTION public.pamda_admin_criar_rede(p_nome text, p_codigo text, p_matriz_cliente_id uuid, p_tipo text DEFAULT 'rede'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_id uuid;v_code text;v_legacy_code text;
BEGIN
 IF NOT public.pamda_is_admin() THEN RAISE EXCEPTION 'Acesso restrito à administração' USING ERRCODE='42501'; END IF;
 v_code:=btrim(coalesce(p_codigo,''));
 IF btrim(coalesce(p_nome,''))='' OR v_code !~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$' OR
   p_tipo NOT IN ('rede','franquia','grupo_comercial') THEN
  RAISE EXCEPTION 'Nome, código ou tipo da rede inválido';
 END IF;
 SELECT customer_code INTO v_legacy_code FROM public.customers
  WHERE id=p_matriz_cliente_id AND active FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Cliente principal ativo não encontrado'; END IF;
 IF EXISTS(SELECT 1 FROM public.erp_customer_network_members WHERE customer_id=p_matriz_cliente_id) THEN
  RAISE EXCEPTION 'Cliente já pertence a uma rede';
 END IF;
 INSERT INTO public.erp_customer_networks(network_name,network_code,network_kind,headquarters_customer_id,created_by)
 VALUES(btrim(p_nome),v_code,p_tipo,p_matriz_cliente_id,(SELECT auth.uid())) RETURNING id INTO v_id;
 INSERT INTO public.erp_customer_network_members(network_id,customer_id,unit_sequence,display_code,legacy_customer_code,joined_by)
 VALUES(v_id,p_matriz_cliente_id,0,v_code,v_legacy_code,(SELECT auth.uid()));
 INSERT INTO public.erp_commercial_change_audit(actor_user_id,customer_id,action,after_data,reason)
 VALUES((SELECT auth.uid()),p_matriz_cliente_id,'criar_rede_comercial',
 jsonb_build_object('network_id',v_id,'name',btrim(p_nome),'network_code',v_code),'Agrupamento comercial sem alteração dos códigos anteriores');
 RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.pamda_admin_vincular_cliente_rede(p_rede_id uuid, p_cliente_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_code text;v_legacy text;v_seq integer;v_display text;v_primary uuid;
BEGIN
 IF NOT public.pamda_is_admin() THEN RAISE EXCEPTION 'Acesso restrito à administração' USING ERRCODE='42501'; END IF;
 IF p_rede_id IS NULL OR p_cliente_id IS NULL THEN RAISE EXCEPTION 'Rede ou cliente ausente'; END IF;
 SELECT network_code,headquarters_customer_id INTO v_code,v_primary
 FROM public.erp_customer_networks WHERE id=p_rede_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Rede não encontrada'; END IF;
 SELECT customer_code INTO v_legacy FROM public.customers WHERE id=p_cliente_id AND active FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Cliente não encontrado ou inativo'; END IF;
 IF EXISTS(SELECT 1 FROM public.erp_customer_network_members WHERE customer_id=p_cliente_id) THEN
   RAISE EXCEPTION 'Este cliente já pertence a uma rede';
 END IF;
 SELECT COALESCE(MAX(unit_sequence),0)+1 INTO v_seq
 FROM public.erp_customer_network_members WHERE network_id=p_rede_id;
 v_display:=v_code||'-'||v_seq::text;
 INSERT INTO public.erp_customer_network_members(network_id,customer_id,unit_sequence,display_code,legacy_customer_code,joined_by)
 VALUES(p_rede_id,p_cliente_id,v_seq,v_display,v_legacy,(SELECT auth.uid()));
 INSERT INTO public.erp_commercial_change_audit(actor_user_id,customer_id,action,after_data,reason)
 VALUES((SELECT auth.uid()),p_cliente_id,'vincular_cliente_rede',
 jsonb_build_object('network_id',p_rede_id,'display_code',v_display,'original_code',v_legacy,'headquarters_customer_id',v_primary),
 'Vínculo de grupo sem alterar pedidos e cadastro original');
 RETURN v_display;
END;
$function$

CREATE OR REPLACE FUNCTION public.pamda_admin_configurar_cobranca_rede(p_rede_id uuid, p_ciclo text, p_modo text, p_dias integer, p_observacoes text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_before jsonb;v_after jsonb;v_head uuid;
BEGIN
 IF NOT public.pamda_is_admin() THEN RAISE EXCEPTION 'Acesso negado' USING ERRCODE='42501'; END IF;
 IF p_ciclo IS NULL OR p_ciclo NOT IN ('diario','semanal','mensal','flexivel') OR
  p_modo IS NULL OR p_modo NOT IN ('por_unidade','centralizado','flexivel') OR
  (p_dias IS NOT NULL AND (p_dias<0 OR p_dias>365)) THEN
   RAISE EXCEPTION 'Configuração de rede inválida';
 END IF;
 SELECT to_jsonb(n),headquarters_customer_id INTO v_before,v_head
 FROM public.erp_customer_networks n WHERE id=p_rede_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Rede não encontrada'; END IF;
 UPDATE public.erp_customer_networks SET default_cycle=p_ciclo,
  default_collection_mode=p_modo,default_due_days=p_dias,notes=p_observacoes,updated_at=now()
 WHERE id=p_rede_id;
 SELECT to_jsonb(n) INTO v_after FROM public.erp_customer_networks n WHERE id=p_rede_id;
 INSERT INTO public.erp_commercial_change_audit(actor_user_id,customer_id,action,before_data,after_data)
 VALUES((SELECT auth.uid()),v_head,'configurar_cobranca_rede',v_before,v_after);
END;
$function$

CREATE OR REPLACE FUNCTION public.pamda_admin_editar_produto(p_produto_id uuid, p_expected_updated_at timestamp with time zone, p_changes jsonb, p_motivo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_old public.products%ROWTYPE;
  v_new public.products%ROWTYPE;
  v_bad text;
BEGIN
  IF NOT public.pamda_is_admin() THEN
    RAISE EXCEPTION 'Somente administrador ativo pode editar produtos' USING ERRCODE='42501';
  END IF;
  IF p_produto_id IS NULL OR p_expected_updated_at IS NULL
     OR p_changes IS NULL OR jsonb_typeof(p_changes)<>'object'
     OR p_changes='{}'::jsonb OR length(btrim(coalesce(p_motivo,'')))<5 THEN
    RAISE EXCEPTION 'Produto, versão, alteração e motivo são obrigatórios';
  END IF;

  SELECT keys.key INTO v_bad
  FROM jsonb_object_keys(p_changes) AS keys(key)
  WHERE keys.key NOT IN ('name','description','category','brand','model_phone',
    'current_cost','managerial_cost','sale_price','image_url')
  LIMIT 1;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'Campo não editável nesta tela: %', v_bad;
  END IF;
  IF (p_changes ? 'name' AND (jsonb_typeof(p_changes->'name')<>'string'
       OR length(btrim(p_changes->>'name')) NOT BETWEEN 2 AND 160))
     OR (p_changes ? 'category' AND (jsonb_typeof(p_changes->'category')<>'string'
       OR length(btrim(p_changes->>'category')) NOT BETWEEN 1 AND 160))
     OR (p_changes ? 'brand' AND (jsonb_typeof(p_changes->'brand')<>'string'
       OR length(btrim(p_changes->>'brand')) NOT BETWEEN 1 AND 100))
     OR (p_changes ? 'description' AND jsonb_typeof(p_changes->'description') NOT IN ('string','null'))
     OR (p_changes ? 'model_phone' AND jsonb_typeof(p_changes->'model_phone') NOT IN ('string','null'))
     OR (p_changes ? 'image_url' AND jsonb_typeof(p_changes->'image_url') NOT IN ('string','null')) THEN
    RAISE EXCEPTION 'Campos textuais inválidos';
  END IF;
  IF (p_changes ? 'current_cost' AND jsonb_typeof(p_changes->'current_cost') NOT IN ('number','null'))
     OR (p_changes ? 'managerial_cost' AND jsonb_typeof(p_changes->'managerial_cost') NOT IN ('number','null'))
     OR (p_changes ? 'sale_price' AND jsonb_typeof(p_changes->'sale_price') NOT IN ('number','null')) THEN
    RAISE EXCEPTION 'Custos e preço devem ser números ou NULL';
  END IF;
  IF (p_changes ? 'current_cost' AND p_changes->>'current_cost' IS NOT NULL
       AND (p_changes->>'current_cost')::numeric<0)
     OR (p_changes ? 'managerial_cost' AND p_changes->>'managerial_cost' IS NOT NULL
       AND (p_changes->>'managerial_cost')::numeric<0)
     OR (p_changes ? 'sale_price' AND p_changes->>'sale_price' IS NOT NULL
       AND (p_changes->>'sale_price')::numeric<0) THEN
    RAISE EXCEPTION 'Custos e preço não podem ser negativos';
  END IF;
  IF p_changes ? 'model_phone' AND p_changes->>'model_phone' IS NOT NULL
     AND length(btrim(p_changes->>'model_phone'))>160 THEN
    RAISE EXCEPTION 'Modelo do celular inválido';
  END IF;
  IF p_changes ? 'image_url' AND p_changes->>'image_url' IS NOT NULL
     AND (p_changes->>'image_url' !~* '^https://[^[:space:]]+$'
       OR length(p_changes->>'image_url')>2000) THEN
    RAISE EXCEPTION 'A imagem precisa de uma URL HTTPS válida';
  END IF;

  SELECT * INTO v_old FROM public.products WHERE id=p_produto_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Produto não encontrado'; END IF;
  IF NOT v_old.active THEN RAISE EXCEPTION 'Produto arquivado não pode ser editado'; END IF;
  IF v_old.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'Produto foi alterado em outra sessão. Atualize a página';
  END IF;
  IF v_old.type='kit' AND p_changes ? 'sale_price'
     AND p_changes->>'sale_price' IS NULL
     AND (v_old.b2b_site_visible OR EXISTS (
       SELECT 1 FROM public.erp_panda_ia_phone_models m
       WHERE m.kit_product_id=v_old.id AND m.published
     )) THEN
    RAISE EXCEPTION 'Despublique o modelo Panda IA antes de remover o preço do kit';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.erp_panda_ia_phone_models m
    WHERE m.published AND (m.kit_product_id=v_old.id OR m.base_product_id=v_old.id)
  ) AND (p_changes ? 'name' OR p_changes ? 'brand' OR p_changes ? 'model_phone') THEN
    RAISE EXCEPTION 'Despublique o modelo Panda IA antes de alterar nome, marca ou modelo';
  END IF;

  UPDATE public.products SET
    name=CASE WHEN p_changes ? 'name' THEN btrim(p_changes->>'name') ELSE name END,
    description=CASE WHEN p_changes ? 'description' THEN p_changes->>'description' ELSE description END,
    category=CASE WHEN p_changes ? 'category' THEN btrim(p_changes->>'category') ELSE category END,
    brand=CASE WHEN p_changes ? 'brand' THEN btrim(p_changes->>'brand') ELSE brand END,
    model_phone=CASE WHEN p_changes ? 'model_phone' THEN nullif(btrim(p_changes->>'model_phone'),'') ELSE model_phone END,
    current_cost=CASE WHEN p_changes ? 'current_cost' THEN (p_changes->>'current_cost')::numeric ELSE current_cost END,
    managerial_cost=CASE WHEN p_changes ? 'managerial_cost' THEN (p_changes->>'managerial_cost')::numeric ELSE managerial_cost END,
    sale_price=CASE WHEN p_changes ? 'sale_price' THEN (p_changes->>'sale_price')::numeric ELSE sale_price END,
    image_url=CASE WHEN p_changes ? 'image_url' THEN nullif(btrim(p_changes->>'image_url'),'') ELSE image_url END,
    updated_at=clock_timestamp()
  WHERE id=p_produto_id
  RETURNING * INTO v_new;

  INSERT INTO public.erp_product_admin_audit(product_id,actor_user_id,action,before_data,after_data,reason)
  VALUES(p_produto_id,(SELECT auth.uid()),'editar_produto',to_jsonb(v_old),to_jsonb(v_new),btrim(p_motivo));
  RETURN jsonb_build_object('id',v_new.id,'code',v_new.code,'sku',v_new.sku,
    'type',v_new.type,'updated_at',v_new.updated_at);
END;
$function$

CREATE OR REPLACE FUNCTION public.pamda_admin_salvar_modelo_panda_ia(p_kit_id uuid, p_nome text, p_marca text, p_imagem_url text, p_mascara_url text, p_conferido boolean, p_publicar boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_kit public.products%ROWTYPE;v_base uuid;v_before jsonb;v_new jsonb;
 v_body text;v_mask text;
BEGIN
 IF NOT public.pamda_is_admin() THEN RAISE EXCEPTION 'Acesso restrito ao administrador' USING ERRCODE='42501'; END IF;
 SELECT * INTO v_kit FROM public.products WHERE id=p_kit_id AND type='kit' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Kit não encontrado'; END IF;
 SELECT p.id INTO v_base FROM public.kit_components kc
 JOIN public.products p ON p.id=kc.component_product_id
 WHERE kc.kit_product_id=p_kit_id AND p.type='fisico';
 IF v_base IS NULL THEN RAISE EXCEPTION 'Kit sem capa-base física'; END IF;
 IF length(btrim(coalesce(p_nome,''))) NOT BETWEEN 2 AND 160 OR
  length(btrim(coalesce(p_marca,''))) NOT BETWEEN 2 AND 100 OR
  p_conferido IS NULL OR p_publicar IS NULL THEN RAISE EXCEPTION 'Modelo, marca ou confirmação inválidos'; END IF;
 v_body:=nullif(btrim(coalesce(p_imagem_url,'')),'');
 v_mask:=nullif(btrim(coalesce(p_mascara_url,'')),'');
 IF (v_body IS NOT NULL AND (v_body !~* '^https://[^[:space:]]+$' OR length(v_body)>2000))
  OR (v_mask IS NOT NULL AND (v_mask !~* '^https://[^[:space:]]+$' OR length(v_mask)>2000)) THEN
   RAISE EXCEPTION 'URLs de imagem ou máscara inválidas';
 END IF;
 IF p_publicar AND (NOT p_conferido OR v_body IS NULL OR v_mask IS NULL OR
  NOT v_kit.active OR v_kit.sale_price IS NULL) THEN
  RAISE EXCEPTION 'Para publicar, confirme visualmente imagem e máscara e configure kit ativo com preço';
 END IF;
 SELECT to_jsonb(t) INTO v_before FROM public.erp_panda_ia_phone_models t WHERE kit_product_id=p_kit_id;
 INSERT INTO public.erp_panda_ia_phone_models(
  kit_product_id,base_product_id,model_label,brand,body_url,mask_url,
  technical_verified,published,source,updated_by
 ) VALUES(p_kit_id,v_base,btrim(p_nome),btrim(p_marca),
          v_body,v_mask,p_conferido,p_publicar,'erp_manual',(SELECT auth.uid()))
 ON CONFLICT(kit_product_id) DO UPDATE SET
  base_product_id=excluded.base_product_id,model_label=excluded.model_label,
  brand=excluded.brand,body_url=excluded.body_url,mask_url=excluded.mask_url,
  technical_verified=excluded.technical_verified,published=excluded.published,
  source=excluded.source,updated_by=excluded.updated_by,updated_at=now();
 UPDATE public.products SET b2b_site_visible=p_publicar,updated_at=now()
 WHERE id=p_kit_id AND b2b_site_visible IS DISTINCT FROM p_publicar;
 SELECT to_jsonb(t) INTO v_new FROM public.erp_panda_ia_phone_models t WHERE kit_product_id=p_kit_id;
 INSERT INTO public.erp_product_admin_audit(product_id,actor_user_id,action,before_data,after_data)
 VALUES(p_kit_id,(SELECT auth.uid()),'salvar_modelo_panda_ia',v_before,v_new);
 RETURN jsonb_build_object('kit_id',p_kit_id,'published',p_publicar,'model',v_new);
END;
$function$

CREATE OR REPLACE FUNCTION private.pamda_admin_produto_acao_impl(p_produto_id uuid, p_acao text, p_expected_updated_at timestamp with time zone, p_dados jsonb, p_motivo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_old public.products%ROWTYPE;
  v_new public.products%ROWTYPE;
  v_link_old public.products%ROWTYPE;
  v_link_new public.products%ROWTYPE;
  v_link_id uuid;
  v_link_count integer;
  v_sku text;
  v_link_sku text;
  v_expected_linked timestamptz;
  v_bad text;
BEGIN
  IF NOT public.pamda_is_admin() THEN
    RAISE EXCEPTION 'Somente administrador ativo pode alterar produtos' USING ERRCODE='42501';
  END IF;
  IF p_produto_id IS NULL OR p_expected_updated_at IS NULL
     OR p_dados IS NULL OR jsonb_typeof(p_dados)<>'object'
     OR length(btrim(coalesce(p_motivo,'')))<5 THEN
    RAISE EXCEPTION 'Produto, versão, dados e motivo são obrigatórios';
  END IF;
  IF p_acao IS NULL OR p_acao NOT IN ('alterar_sku','arquivar') THEN
    RAISE EXCEPTION 'Ação de produto inválida';
  END IF;
  SELECT * INTO v_old FROM public.products WHERE id=p_produto_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Produto não encontrado'; END IF;
  IF NOT v_old.active THEN RAISE EXCEPTION 'Produto já está arquivado'; END IF;
  IF v_old.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'Produto foi alterado em outra sessão. Atualize a página';
  END IF;

  IF p_acao='alterar_sku' THEN
    SELECT keys.key INTO v_bad FROM jsonb_object_keys(p_dados) AS keys(key)
    WHERE keys.key NOT IN ('sku','linked_sku','linked_product_id','expected_linked_updated_at')
    LIMIT 1;
    IF v_bad IS NOT NULL OR NOT (p_dados ? 'sku')
       OR jsonb_typeof(p_dados->'sku') IS DISTINCT FROM 'string'
       OR (p_dados ? 'linked_sku' AND jsonb_typeof(p_dados->'linked_sku') NOT IN ('string','null'))
       OR (p_dados ? 'linked_product_id' AND jsonb_typeof(p_dados->'linked_product_id') NOT IN ('string','null'))
       OR (p_dados ? 'expected_linked_updated_at' AND jsonb_typeof(p_dados->'expected_linked_updated_at') NOT IN ('string','null')) THEN
      RAISE EXCEPTION 'Dados de SKU inválidos';
    END IF;
    v_sku:=upper(btrim(p_dados->>'sku'));
    IF v_sku IS NULL OR length(v_sku) NOT BETWEEN 2 AND 100 THEN RAISE EXCEPTION 'SKU inválido'; END IF;
    IF v_sku=upper(btrim(v_old.sku)) THEN RAISE EXCEPTION 'Informe um SKU diferente do atual'; END IF;
    -- O kit nunca pode ser renomeado independentemente da capa. Kits especiais
    -- e componentes não físicos exigem revisão, sem tentar inferir outro par.
    IF v_old.type='kit' THEN
      RAISE EXCEPTION 'Altere o SKU pela capa vinculada; kits especiais exigem revisão administrativa';
    END IF;
    IF v_old.type<>'fisico' AND EXISTS (
      SELECT 1 FROM public.kit_components WHERE component_product_id=v_old.id
    ) THEN
      RAISE EXCEPTION 'Componente de kit especial exige revisão administrativa';
    END IF;
    IF v_old.type='fisico' THEN
      SELECT count(*) INTO v_link_count
      FROM public.kit_components kc
      JOIN public.products k ON k.id=kc.kit_product_id AND k.type='kit'
      WHERE kc.component_product_id=v_old.id;
      IF v_link_count>1 THEN RAISE EXCEPTION 'Produto possui vários kits vinculados; alteração bloqueada'; END IF;
      IF v_link_count=1 THEN
        SELECT kc.kit_product_id INTO v_link_id
        FROM public.kit_components kc
        JOIN public.products k ON k.id=kc.kit_product_id AND k.type='kit'
        WHERE kc.component_product_id=v_old.id
        LIMIT 1;
      END IF;
    ELSE
      v_link_count:=0;
    END IF;
    IF v_link_count=1 THEN
      IF nullif(p_dados->>'linked_product_id','') IS DISTINCT FROM v_link_id::text
         OR p_dados->>'expected_linked_updated_at' IS NULL THEN
        RAISE EXCEPTION 'Atualize o catálogo para confirmar o kit vinculado';
      END IF;
      v_expected_linked:=(p_dados->>'expected_linked_updated_at')::timestamptz;
      SELECT * INTO v_link_old FROM public.products WHERE id=v_link_id FOR UPDATE;
      IF NOT FOUND OR v_link_old.updated_at IS DISTINCT FROM v_expected_linked THEN
        RAISE EXCEPTION 'Kit vinculado foi alterado em outra sessão. Atualize a página';
      END IF;
      IF v_old.sku IN ('CAP-CARTEIRA','CAP-MAGSAFE','CAP-SPACE','CAP-VELUDO')
         OR v_sku IN ('CAP-CARTEIRA','CAP-MAGSAFE','CAP-SPACE','CAP-VELUDO')
         OR v_link_old.sku IS DISTINCT FROM 'KIT-'||v_old.sku
         OR (SELECT count(*) FROM public.kit_components WHERE kit_product_id=v_link_id)<>2
         OR NOT EXISTS (
           SELECT 1 FROM public.kit_components kc
           WHERE kc.kit_product_id=v_link_id AND kc.component_product_id=v_old.id AND kc.quantity=1
         ) OR NOT EXISTS (
           SELECT 1 FROM public.kit_components kc JOIN public.products s ON s.id=kc.component_product_id
           WHERE kc.kit_product_id=v_link_id AND s.type='servico' AND s.sku='SRV-DTF-UV' AND kc.quantity=1
         ) THEN
        RAISE EXCEPTION 'Kit especial ou incoerente exige revisão administrativa';
      END IF;
      v_link_sku:='KIT-'||v_sku;
      IF length(v_link_sku)>100 THEN RAISE EXCEPTION 'SKU da capa excede o limite para gerar o SKU do kit'; END IF;
      -- Compatibilidade com clientes anteriores: só aceita o valor derivado.
      IF p_dados->>'linked_sku' IS NOT NULL
         AND p_dados->>'linked_sku' IS DISTINCT FROM v_link_sku THEN
        RAISE EXCEPTION 'SKU do kit deve ser KIT- seguido do SKU da capa';
      END IF;
      IF v_link_sku=upper(btrim(v_link_old.sku)) OR v_sku=upper(btrim(v_link_old.sku)) THEN
        RAISE EXCEPTION 'Informe um SKU diferente do kit atual';
      END IF;
    ELSIF p_dados->>'linked_sku' IS NOT NULL OR p_dados->>'linked_product_id' IS NOT NULL
       OR p_dados->>'expected_linked_updated_at' IS NOT NULL THEN
      RAISE EXCEPTION 'Este produto não possui kit vinculado para alterar';
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.products p
      WHERE upper(btrim(p.sku))=v_sku AND p.id<>v_old.id AND (v_link_count=0 OR p.id<>v_link_id)
    ) OR (v_link_count=1 AND EXISTS (
      SELECT 1 FROM public.products p
      WHERE upper(btrim(p.sku))=v_link_sku AND p.id<>v_old.id AND p.id<>v_link_id
    )) THEN
      RAISE EXCEPTION 'SKU informado já existe, inclusive em produto arquivado';
    END IF;

    UPDATE public.products SET sku=v_sku,updated_at=clock_timestamp()
    WHERE id=v_old.id RETURNING * INTO v_new;
    INSERT INTO public.erp_product_admin_audit(product_id,actor_user_id,action,before_data,after_data,reason)
    VALUES(v_old.id,(SELECT auth.uid()),'alterar_sku',to_jsonb(v_old),to_jsonb(v_new),btrim(p_motivo));
    IF v_link_count=1 THEN
      UPDATE public.products SET sku=v_link_sku,updated_at=clock_timestamp()
      WHERE id=v_link_id RETURNING * INTO v_link_new;
      INSERT INTO public.erp_product_admin_audit(product_id,actor_user_id,action,before_data,after_data,reason)
      VALUES(v_link_id,(SELECT auth.uid()),'alterar_sku',to_jsonb(v_link_old),to_jsonb(v_link_new),btrim(p_motivo));
    END IF;
    RETURN jsonb_build_object('action',p_acao,'id',v_new.id,'sku',v_new.sku,
      'linked_product_id',v_link_id,'linked_sku',v_link_new.sku);
  END IF;

  IF (SELECT count(*) FROM jsonb_object_keys(p_dados))<>1
     OR jsonb_typeof(p_dados->'confirm_sku') IS DISTINCT FROM 'string'
     OR p_dados->>'confirm_sku' IS DISTINCT FROM v_old.sku THEN
    RAISE EXCEPTION 'Digite exatamente o SKU atual para confirmar o arquivamento';
  END IF;
  IF v_old.b2b_site_visible OR EXISTS (
    SELECT 1 FROM public.erp_panda_ia_phone_models m
    WHERE m.published AND (m.kit_product_id=v_old.id OR m.base_product_id=v_old.id)
  ) THEN
    RAISE EXCEPTION 'Despublique o modelo Panda IA antes de arquivar este produto';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.kit_components kc
    JOIN public.products k ON k.id=kc.kit_product_id
    WHERE kc.component_product_id=v_old.id AND k.type='kit' AND k.active
  ) THEN
    RAISE EXCEPTION 'Arquive primeiro os kits ativos vinculados a este produto';
  END IF;
  UPDATE public.products SET active=false,updated_at=clock_timestamp()
  WHERE id=v_old.id RETURNING * INTO v_new;
  INSERT INTO public.erp_product_admin_audit(product_id,actor_user_id,action,before_data,after_data,reason)
  VALUES(v_old.id,(SELECT auth.uid()),'arquivar_produto',to_jsonb(v_old),to_jsonb(v_new),btrim(p_motivo));
  RETURN jsonb_build_object('action',p_acao,'id',v_new.id,'active',v_new.active,
    'updated_at',v_new.updated_at);
END;
$function$

CREATE OR REPLACE FUNCTION public.pamda_admin_criar_capa_com_kit(p_modelo text, p_marca text, p_sku_capa text, p_preco_capa numeric, p_preco_kit numeric, p_custo_capa numeric DEFAULT NULL::numeric, p_custo_gerencial_capa numeric DEFAULT NULL::numeric, p_custo_gerencial_kit numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_model text;v_brand text;v_case_id uuid;v_case_code text;v_case_sku text;
 v_kit_id uuid;v_kit_code text;v_kit_sku text;v_service_id uuid;
BEGIN
 IF NOT public.pamda_is_admin() THEN RAISE EXCEPTION 'Somente administrador pode cadastrar produtos' USING ERRCODE='42501'; END IF;
 v_model:=btrim(coalesce(p_modelo,''));
 v_brand:=btrim(coalesce(p_marca,''));
 IF length(v_model) NOT BETWEEN 2 AND 160 OR length(v_brand) NOT BETWEEN 2 AND 100
    OR length(btrim(coalesce(p_sku_capa,''))) NOT BETWEEN 2 AND 100 THEN
   RAISE EXCEPTION 'Informe modelo, marca e SKU válidos';
 END IF;
 IF p_preco_capa IS NULL OR p_preco_capa<=0 OR p_preco_kit IS NULL OR p_preco_kit<=0
    OR p_preco_kit < p_preco_capa
    OR (p_custo_capa IS NOT NULL AND p_custo_capa<0)
    OR (p_custo_gerencial_capa IS NOT NULL AND p_custo_gerencial_capa<0)
    OR (p_custo_gerencial_kit IS NOT NULL AND p_custo_gerencial_kit<0)
 THEN RAISE EXCEPTION 'Preços e custos inválidos; confirme valores reais'; END IF;
 SELECT id INTO v_service_id FROM public.products WHERE sku='SRV-DTF-UV' AND type='servico' AND active;
 IF v_service_id IS NULL THEN RAISE EXCEPTION 'Serviço SRV-DTF-UV não configurado'; END IF;
 IF EXISTS(SELECT 1 FROM public.products WHERE upper(btrim(sku))=upper(btrim(p_sku_capa))
  OR upper(btrim(sku))='KIT-'||upper(btrim(p_sku_capa))) THEN
   RAISE EXCEPTION 'SKU da capa ou do kit já existe';
 END IF;
 SELECT produto_id,codigo,sku INTO v_case_id,v_case_code,v_case_sku
 FROM public.pamda_cadastrar_item_basico('fisico','Capa TPU transparente - '||v_model,
    p_sku_capa,'Capas TPU Transparente',v_brand,v_model,
    p_custo_capa,p_preco_capa,p_custo_gerencial_capa,false,NULL);
 SELECT kit_id,codigo,sku INTO v_kit_id,v_kit_code,v_kit_sku
 FROM public.pamda_cadastrar_kit(v_case_id,v_service_id,p_preco_kit,p_custo_gerencial_kit);
 INSERT INTO public.erp_panda_ia_phone_models(
  kit_product_id,base_product_id,model_label,brand,source,updated_by
 ) VALUES(v_kit_id,v_case_id,v_model,v_brand,'erp_manual',(SELECT auth.uid()));
 INSERT INTO public.erp_product_admin_audit(product_id,actor_user_id,action,after_data,reason)
 VALUES
 (v_case_id,(SELECT auth.uid()),'cadastrar_capa_base',
  jsonb_build_object('code',v_case_code,'sku',v_case_sku,'model',v_model,'brand',v_brand,
   'unit_price',p_preco_capa),'Cadastro manual para homologação'),
 (v_kit_id,(SELECT auth.uid()),'cadastrar_kit_personalizado',
  jsonb_build_object('code',v_kit_code,'sku',v_kit_sku,'case_id',v_case_id,
   'service_id',v_service_id,'unit_price',p_preco_kit),
  'Kit vinculado à capa e ao serviço DTF UV');
 RETURN jsonb_build_object(
  'case_id',v_case_id,'case_code',v_case_code,'case_sku',v_case_sku,
  'kit_id',v_kit_id,'kit_code',v_kit_code,'kit_sku',v_kit_sku,
  'model',v_model,'published',false,'stock_verified',false
 );
END;
$function$

CREATE OR REPLACE FUNCTION public.pamda_user_save(p_data jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_user uuid:=(p_data->>'user_id')::uuid; v_permission record;
begin
 if not public.pamda_is_admin() then raise exception 'Administração de usuários restrita ao administrador' using errcode='42501'; end if;
 if p_data->>'role' not in ('admin_gerencial','gerencial','venda_atendimento','financeiro','producao','estoque_expedicao') or
 coalesce(length(btrim(p_data->>'display_name')),0)=0 or p_data->>'active' is null then raise exception 'Perfil inválido'; end if;
 if v_user=auth.uid() and (p_data->>'role'<>'admin_gerencial' or not (p_data->>'active')::boolean) then raise exception 'Não remova o próprio acesso administrativo'; end if;
 update public.erp_user_profiles set display_name=btrim(p_data->>'display_name'),role=p_data->>'role',active=(p_data->>'active')::boolean,
 can_view_financial_metrics=coalesce((p_data->>'can_view_financial_metrics')::boolean,false),updated_at=now() where user_id=v_user;
 if not found then raise exception 'Perfil inexistente'; end if;
 if jsonb_typeof(p_data->'permissions') is distinct from 'object' then raise exception 'Permissões inválidas'; end if;
 for v_permission in select key,value from jsonb_each(p_data->'permissions') loop
 if not exists(select 1 from public.erp_permission_catalog where key=v_permission.key) or jsonb_typeof(v_permission.value)<>'boolean' then raise exception 'Permissão inválida'; end if;
 insert into public.erp_user_permission_overrides(user_id,permission_key,allowed,reason,assigned_by,updated_at)
 values(v_user,v_permission.key,(v_permission.value::text)::boolean,'Configurado no ERP',auth.uid(),now())
 on conflict(user_id,permission_key) do update set allowed=excluded.allowed,reason=excluded.reason,assigned_by=excluded.assigned_by,updated_at=now();
 end loop;
 insert into public.erp_access_audit(actor_user_id,target_user_id,action,details) values(auth.uid(),v_user,'user.configured',p_data-'password');
end $function$
